function S({registerIndicator:g,sourceValues:A,nulls:c}){g({id:"oa-ubands",name:"Ehlers Ultimate Bands (UBANDS)",category:"Channels",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for smoothing and RMS calculation."},{key:"mult",type:"number",label:"RMS Multiplier",default:1,min:.01,max:100,step:.1,tooltip:"Band width as multiple of RMS value."}],plots:[{key:"middle",type:"line",title:"Middle Band",style:{color:"#ffeb3b",lineWidth:2}},{key:"upper",type:"line",title:"Upper Band",style:{color:"#ffeb3b",lineWidth:2}},{key:"lower",type:"line",title:"Lower Band",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["upper","lower"],colorUp:"#2962ff",colorDown:"#2962ff",opacity:.1}],calc(d,u){const h=Math.max(1,Math.floor(Number(u.length)||20)),y=Math.max(.01,Number(u.mult)||1),m=A(d,u.source??"close"),M=Math.SQRT2*Math.PI/Math.max(1,h),f=Math.exp(-M),p=2*f*Math.cos(M),b=-f*f,N=(1+p-b)/4,o=d.length,t=new Array(o).fill(NaN),w=new Array(o).fill(NaN);for(let e=0;e<o;e++){const l=m[e],i=e>0?m[e-1]:NaN,r=e>1?m[e-2]:NaN,n=Number.isFinite(l)?l:Number.isFinite(i)?i:NaN;if(!Number.isFinite(n))continue;const a=Number.isFinite(i)?i:n,s=Number.isFinite(r)?r:a;e<2||!Number.isFinite(t[e-1])||!Number.isFinite(t[e-2])?t[e]=n:t[e]=(1-N)*n+(2*N-p)*a-(N+b)*s+p*t[e-1]+b*t[e-2],Number.isFinite(l)&&(w[e]=l-t[e])}const k=new Array(o).fill(NaN),F=new Array(o).fill(NaN),x=new Array(o).fill(NaN);for(let e=0;e<o;e++){if(!Number.isFinite(t[e]))continue;let l=0,i=0;for(let n=0;n<h;n++){const a=e-n;if(a<0)break;const s=w[a];Number.isFinite(s)&&(l+=s*s,i+=1)}const r=i>0?Math.sqrt(l/i):0;F[e]=t[e],k[e]=t[e]+y*r,x[e]=t[e]-y*r}return{middle:c(F),upper:c(k),lower:c(x)}}})}export{S as default};
